// The playground's catalog as an A2UI v1.0 catalog document: what a renderer
// outside React (Lit, Angular, Flutter, SwiftUI) implements, and what an A2UI
// agent SDK loads. Generated by `pnpm catalog:export`.
import catalog from "@/a2ui/export/catalog.json";

export const dynamic = "force-static";

export function GET() {
  return Response.json(catalog, { headers: { "Access-Control-Allow-Origin": "*", "Cache-Control": "public, max-age=300" } });
}
